 "content": "def transform(grid):
    # Copy the vertical three-cell template of 5s, centered on each 4 marker.
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    targets = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    source = next(((r, c) for r in range(h - 2) for c in range(w)
                   if grid[r][c] == grid[r+1][c] == grid[r+2][c] == 5), None)
    if source is None:
        return g
    sr, sc = source
    for r, c in targets:
        for dr in (-1, 0, 1):
            rr, cc = r + dr, c + (sc - sc)
            if 0 <= rr < h and 0 <= cc < w:
                g[rr][cc] = 5
    return g
